const missions=[
 {name:'A biblioteca',topic:'HTML',icon:'▤',color:'#e5edce',desc:'Dá estrutura às primeiras páginas da escola.'},
 {name:'O ponto de encontro',topic:'CSS · FLEXBOX',icon:'⇄',color:'#dcebe4',desc:'Alinha ideias. Encontra o lugar de cada elemento.'},
 {name:'O mural de atividades',topic:'CSS · GRID',icon:'▦',color:'#eee3d3',desc:'Transforma espaços vazios numa grelha de possibilidades.'},
 {name:'A loja da escola',topic:'JAVASCRIPT',icon:'◈',color:'#e4e0f0',desc:'Põe os números a trabalhar e dá vida à interface.'},
 {name:'A secretaria',topic:'JS · FORMULÁRIOS',icon:'☷',color:'#f1e4cc',desc:'Liga pessoas, valida dados e termina a reconstrução.'}
];
const check=(label,expr)=>({label,expr});
const cards='<div class="cartao">Robótica</div><div class="cartao">Música</div><div class="cartao">Ciência</div><div class="cartao">Teatro</div><div class="cartao">Desporto</div><div class="cartao">Fotografia</div>';
const menu='<nav class="menu"><b>Escola Digital</b><div class="links"><a href="#">Biblioteca</a><a href="#">Atividades</a><a href="#">Contactos</a></div></nav>';
const robots='<div class="equipa"><span>🤖</span><span>🤖</span><span>🤖</span></div>';
const shop='<label>Quantidade <input id="quantidade" type="number" value="2" min="0"></label><button id="calcular">Calcular</button><p>Total: <output id="total">0</output> €</p>';
const form='<form id="inscricao" novalidate><label>Nome <input id="nome" name="nome"></label><label>Email <input id="email" name="email" type="email"></label><button>Inscrever</button><p id="mensagem" role="status"></p></form>';
const challenges=[];
function add(m,title,mode,objective,lesson,start,solution,tests,hints,html='',controls=null){challenges.push({id:challenges.length,m,title,mode,objective,lesson,start,solution,tests,hints,html,controls});}
add(0,'01 / Uma página com identidade','html','Cria um título principal com o texto Biblioteca e um parágrafo de apresentação.','<code>h1</code> identifica o título principal. <code>p</code> representa um parágrafo. Experimenta os botões e observa a hierarquia.', '<h1>Biblioteca</h1>\n<!-- Acrescenta um parágrafo -->','<h1>Biblioteca</h1>\n<p>Um lugar para descobrir novas histórias.</p>',[check('O título principal identifica a Biblioteca.',"!!document.querySelector('h1') && document.querySelector('h1').textContent.trim()==='Biblioteca'"),check('Existe um parágrafo com conteúdo.',"!!document.querySelector('p')?.textContent.trim()")],['Escreve o texto entre uma tag de abertura e outra de fecho.','Um parágrafo escreve-se com <p> e </p>.'], '', {type:'title'});
add(0,'02 / Organizar o conhecimento','html','Cria um main com um h1, uma lista não ordenada de pelo menos 3 livros e uma ligação para https://www.rbe.mec.pt com texto.','<code>main</code> contém o conteúdo principal. Uma lista <code>ul</code> contém elementos <code>li</code>. As ligações usam <code>href</code>.','<main>\n  <h1>Os nossos livros</h1>\n  <ul>\n    <li>O Principezinho</li>\n  </ul>\n  <!-- Acrescenta a ligação -->\n</main>','<main>\n  <h1>Os nossos livros</h1>\n  <ul>\n    <li>O Principezinho</li>\n    <li>A Fada Oriana</li>\n    <li>O Cavaleiro da Dinamarca</li>\n  </ul>\n  <a href="https://www.rbe.mec.pt">Rede de Bibliotecas Escolares</a>\n</main>',[check('O conteúdo principal inclui um título.',"!!document.querySelector('main h1')?.textContent.trim()"),check('A lista contém pelo menos três livros.',"document.querySelectorAll('main ul > li').length>=3"),check('A ligação tem o endereço e texto pedidos.',"[...document.querySelectorAll('main a')].some(a=>a.getAttribute('href')==='https://www.rbe.mec.pt' && a.textContent.trim())")],['Coloca os livros dentro do main, cada um no seu li.','A ligação usa a estrutura <a href="endereço">texto</a>.']);
add(0,'03 / A biblioteca está aberta','html','Constrói header, nav, main e footer. Inclui um h1, uma ligação no nav e uma imagem com texto alternativo não vazio no main.','Os elementos semânticos descrevem a função de cada zona. O atributo <code>alt</code> descreve uma imagem para quem não a vê. Está disponível uma imagem local: <code>livro.svg</code>.','<!-- Constrói a página da biblioteca -->','<header><h1>Biblioteca Digital</h1></header>\n<nav><a href="#livros">Ver livros</a></nav>\n<main id="livros">\n  <img src="livro.svg" alt="Livro aberto">\n  <p>Descobre a tua próxima leitura.</p>\n</main>\n<footer>Escola Digital</footer>',[check('Existem as quatro zonas semânticas.',"['header','nav','main','footer'].every(s=>document.querySelector(s))"),check('Há um título e uma ligação com texto.',"!!document.querySelector('h1')?.textContent.trim() && !!document.querySelector('nav a[href]')?.textContent.trim()"),check('A imagem do main tem descrição e origem.',"!!document.querySelector('main img')?.getAttribute('alt')?.trim() && !!document.querySelector('main img')?.getAttribute('src')?.trim()")],['Começa por escrever as quatro zonas, com tags de abertura e fecho.','Dentro de main, usa <img src="livro.svg" alt="Livro aberto">.']);
add(1,'01 / Reunir a equipa','css','Coloca os robôs numa linha, centrados horizontalmente e com gap de 20px.','<code>display: flex</code> ativa Flexbox. No eixo horizontal por defeito, <code>justify-content</code> distribui o espaço. Altera os controlos para explorar.','.equipa {\n  display: flex;\n  justify-content: flex-start;\n  gap: 0px;\n}','.equipa {\n  display: flex;\n  justify-content: center;\n  gap: 20px;\n}',[check('O contentor utiliza Flexbox.',"getComputedStyle(document.querySelector('.equipa')).display==='flex'"),check('Os robôs estão centrados horizontalmente.',"getComputedStyle(document.querySelector('.equipa')).justifyContent==='center'"),check('O intervalo é de 20px.',"getComputedStyle(document.querySelector('.equipa')).columnGap==='20px'")],['Seleciona center para centrar os robôs.','Usa gap: 20px para definir a distância entre eles.'],robots,{type:'flex'});
add(1,'02 / O menu da escola','css','Usa Flexbox no menu, com space-between e alinhamento vertical ao centro. Usa também Flexbox nas links, com gap de 16px.','Podes ter um contentor flex dentro de outro. O menu distribui dois grupos; o grupo <code>.links</code> distribui as ligações.','.menu {\n  min-height: 100px;\n}\n.links {\n\n}','.menu {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  min-height: 100px;\n}\n.links {\n  display: flex;\n  gap: 16px;\n}',[check('O menu é um contentor flex.',"getComputedStyle(document.querySelector('.menu')).display==='flex'"),check('O menu distribui os grupos e centra-os verticalmente.',"getComputedStyle(document.querySelector('.menu')).justifyContent==='space-between' && getComputedStyle(document.querySelector('.menu')).alignItems==='center'"),check('As ligações usam flex e gap de 16px.',"getComputedStyle(document.querySelector('.links')).display==='flex' && getComputedStyle(document.querySelector('.links')).columnGap==='16px'")],['Para separar os dois grupos, usa justify-content: space-between.','align-items: center centra os elementos no eixo transversal.'],menu);
add(1,'03 / Espaço para todos','css','Constrói uma equipa flex que permite quebra de linha. Define gap de 12px e uma largura base (flex-basis) de 120px para cada cartão.','<code>flex-wrap: wrap</code> permite criar novas linhas. <code>flex-basis</code> define o tamanho inicial de cada elemento. Testa também a largura de 320px.','/* Organiza os cartões */\n.equipa {\n}\n.equipa .cartao {\n}','.equipa {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n}\n.equipa .cartao {\n  flex-basis: 120px;\n}',[check('A equipa utiliza flex e permite quebra.',"getComputedStyle(document.querySelector('.equipa')).display==='flex' && getComputedStyle(document.querySelector('.equipa')).flexWrap==='wrap'"),check('O gap é de 12px.',"getComputedStyle(document.querySelector('.equipa')).columnGap==='12px'"),check('Cada cartão tem uma base de 120px.',"[...document.querySelectorAll('.cartao')].every(e=>getComputedStyle(e).flexBasis==='120px')")],['São necessárias regras para o contentor e para os cartões.','No contentor usa flex-wrap: wrap; nos cartões usa flex-basis: 120px.'],'<div class="equipa">'+cards+'</div>');
add(2,'01 / As primeiras colunas','css','Ativa Grid no mural e cria 3 colunas com a mesma largura, separadas por 12px.','<code>grid-template-columns: repeat(3, 1fr)</code> cria três colunas que partilham o espaço disponível.','.mural {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 0px;\n}','.mural {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 12px;\n}',[check('O mural usa Grid.',"getComputedStyle(document.querySelector('.mural')).display==='grid'"),check('Existem três colunas iguais.',"(()=>{let a=getComputedStyle(document.querySelector('.mural')).gridTemplateColumns.split(' ');return a.length===3 && Math.max(...a.map(parseFloat))-Math.min(...a.map(parseFloat))<1})()"),check('O gap é de 12px.',"getComputedStyle(document.querySelector('.mural')).gap==='12px'")],['O número de repetições deve ser 3.','Usa repeat(3, 1fr) e gap: 12px.'],'<div class="mural">'+cards+'</div>',{type:'grid'});
add(2,'02 / Um destaque no mural','css','Mantém três colunas e gap de 12px. Faz o primeiro cartão ocupar as 3 colunas.','<code>grid-column: 1 / -1</code> faz um elemento ocupar desde a primeira até à última linha de coluna.','.mural { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }\n.cartao:first-child {\n  /* Dá destaque ao primeiro cartão */\n}','.mural { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }\n.cartao:first-child {\n  grid-column: 1 / -1;\n}',[check('O mural mantém as três colunas e o gap.',"getComputedStyle(document.querySelector('.mural')).display==='grid' && getComputedStyle(document.querySelector('.mural')).gridTemplateColumns.split(' ').length===3 && getComputedStyle(document.querySelector('.mural')).gap==='12px'"),check('O primeiro cartão ocupa toda a largura.',"Math.abs(document.querySelector('.cartao').getBoundingClientRect().width-document.querySelector('.mural').getBoundingClientRect().width)<2")],['Seleciona o primeiro cartão com .cartao:first-child.','A linha -1 corresponde à última linha da grelha.'],'<div class="mural">'+cards+'</div>');
add(2,'03 / Um mural que se adapta','css','Cria uma grelha com 1 coluna até 399px e 2 colunas a partir de 400px, sempre com gap de 16px. Usa uma media query.','Uma <code>@media (min-width: 400px)</code> aplica regras quando a janela de pré-visualização tem pelo menos 400px. O teste observa ambas as larguras.','.mural {\n  /* Uma coluna por defeito */\n}\n@media (min-width: 400px) {\n  .mural {\n  }\n}','.mural {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 16px;\n}\n@media (min-width: 400px) {\n  .mural { grid-template-columns: repeat(2, 1fr); }\n}',[check('O mural usa Grid com gap de 16px.',"getComputedStyle(document.querySelector('.mural')).display==='grid' && getComputedStyle(document.querySelector('.mural')).gap==='16px'"),check('Tem uma coluna a 320px e duas a 480px.',"responsiveGrid()")],['Começa com uma coluna; dentro da media query define duas.','Usa @media (min-width: 400px) { .mural { grid-template-columns: repeat(2, 1fr); } }.'],'<div class="mural">'+cards+'</div>');
add(3,'01 / O preço certo','js','Completa a função calcularTotal(preco, quantidade), devolvendo o produto dos dois valores. O botão utiliza essa função.','<code>return</code> devolve um resultado. O operador <code>*</code> multiplica dois números. Experimenta diferentes quantidades na pré-visualização.','function calcularTotal(preco, quantidade) {\n  return 0;\n}','function calcularTotal(preco, quantidade) {\n  return preco * quantidade;\n}',[check('A função calcula 3 × 4 = 12.',"calcularTotal(3,4)===12"),check('Funciona com decimais e quantidade zero.',"calcularTotal(2.5,3)===7.5 && calcularTotal(8,0)===0")],['A função já recebe os dois valores nos parâmetros.','Devolve preco * quantidade.'],shop);
add(3,'02 / Desconto de equipa','js','Completa calcularDesconto(total, percentagem). Deve devolver o preço final depois do desconto, sem arredondar.','O valor do desconto é <code>total * percentagem / 100</code>. Subtrai esse valor ao total.','function calcularDesconto(total, percentagem) {\n  return total;\n}','function calcularDesconto(total, percentagem) {\n  return total - total * percentagem / 100;\n}',[check('100 € com 20% de desconto dá 80 €.',"calcularDesconto(100,20)===80"),check('Lida com 0%, 100% e decimais.',"calcularDesconto(30,0)===30 && calcularDesconto(30,100)===0 && Math.abs(calcularDesconto(25,10)-22.5)<0.001")],['Calcula primeiro a parcela que vais descontar.','O resultado é total - total * percentagem / 100.'],'<label>Total (€)<input id="valor" type="number" value="100"></label><label>Desconto (%)<input id="percentagem" type="number" value="20"></label><button id="desconto">Calcular desconto</button><p>Preço final: <output id="final">—</output> €</p>');
add(3,'03 / Uma loja que responde','js','Ao clicar em Calcular, lê a quantidade, converte-a em número e mostra o total no elemento #total. Cada artigo custa 2,50 €.','<code>addEventListener</code> associa uma ação a um evento. <code>Number(input.value)</code> converte o texto. <code>textContent</code> atualiza a página.','const botao = document.querySelector("#calcular");\nbotao.addEventListener("click", function () {\n  // Lê a quantidade e atualiza o total\n});','const botao = document.querySelector("#calcular");\nbotao.addEventListener("click", function () {\n  const quantidade = Number(document.querySelector("#quantidade").value);\n  document.querySelector("#total").textContent = (quantidade * 2.5).toFixed(2);\n});',[check('O clique calcula o total para 4 artigos.',"shopCase(4,10)"),check('O cálculo responde a uma nova quantidade.',"shopCase(3,7.5)"),check('Zero artigos corresponde a zero euros.',"shopCase(0,0)")],['Procura o input pelo id quantidade e lê a propriedade value.','Dentro do evento, atribui quantidade * 2.5 ao textContent de #total.'],shop);
add(4,'01 / Um formulário para todos','html','Cria um formulário com nome e email obrigatórios e um botão de envio. Usa ids nome e email, tipos text e email e labels associadas com for.','Os <code>label</code> identificam os campos. <code>required</code> torna o preenchimento obrigatório. <code>type="email"</code> ativa a validação do navegador.','<form>\n  <label for="nome">Nome</label>\n  <input id="nome" type="text">\n  <!-- Acrescenta o email e o botão -->\n</form>','<form>\n  <label for="nome">Nome</label>\n  <input id="nome" name="nome" type="text" required>\n  <label for="email">Email</label>\n  <input id="email" name="email" type="email" required>\n  <button type="submit">Inscrever</button>\n</form>',[check('O campo nome é obrigatório e tem o tipo correto.',"!!document.querySelector('form #nome[required][type=text]')"),check('O email é obrigatório e do tipo email.',"!!document.querySelector('form #email[required][type=email]')"),check('Os labels estão associados aos dois campos.',"!!document.querySelector('label[for=nome]')?.textContent.trim() && !!document.querySelector('label[for=email]')?.textContent.trim()"),check('Existe um botão de envio.',"!!document.querySelector('form button[type=submit],form input[type=submit]')")],['Acrescenta required aos dois inputs.','O atributo for do label deve coincidir com o id do input.']);
add(4,'02 / Validar antes de inscrever','js','No submit, impede o envio. Se o nome, sem espaços nas extremidades, estiver vazio ou o email for inválido, mostra "Verifica os dados". Caso contrário, mostra "Inscrição concluída" em #mensagem.','Usa <code>event.preventDefault()</code>, <code>trim()</code> e <code>checkValidity()</code>. O formulário tem novalidate para poderes construir o teu próprio feedback.','const formulario = document.querySelector("#inscricao");\nformulario.addEventListener("submit", function (event) {\n  // Impede o envio e valida os campos\n});','const formulario = document.querySelector("#inscricao");\nformulario.addEventListener("submit", function (event) {\n  event.preventDefault();\n  const nome = document.querySelector("#nome").value.trim();\n  const email = document.querySelector("#email");\n  const valido = nome !== "" && email.value !== "" && email.checkValidity();\n  document.querySelector("#mensagem").textContent = valido ? "Inscrição concluída" : "Verifica os dados";\n});',[check('Rejeita um nome vazio e impede o envio.',"formCase('', 'ana@escola.pt', 'Verifica os dados')"),check('Rejeita um email inválido e espaços no nome.',"formCase('Ana','invalido','Verifica os dados') && formCase('   ','ana@escola.pt','Verifica os dados')"),check('Rejeita um email vazio.',"formCase('Ana','','Verifica os dados')"),check('Aceita uma inscrição válida.',"formCase('Ana','ana@escola.pt','Inscrição concluída')")],['Começa pelo event.preventDefault() dentro do evento submit.','Verifica nome.trim(), email.value e email.checkValidity(); usa uma condição para escolher a mensagem.'],form);
add(4,'03 / Confirmar e calcular','js','Valida o número de participantes: inteiro entre 1 e 30. No submit, impede o envio. Se for válido, mostra o custo (5 € por pessoa) em #custo e "Reserva confirmada" em #mensagem. Caso contrário, mostra "Número inválido" e limpa #custo.','<code>Number.isInteger(n)</code> verifica se um número é inteiro. Combina condições com <code>&&</code>.','document.querySelector("form").addEventListener("submit", function (event) {\n  event.preventDefault();\n  // Valida, calcula e apresenta o resultado\n});','document.querySelector("form").addEventListener("submit", function (event) {\n  event.preventDefault();\n  const n = Number(document.querySelector("#participantes").value);\n  const valido = Number.isInteger(n) && n >= 1 && n <= 30;\n  document.querySelector("#custo").textContent = valido ? n * 5 : "";\n  document.querySelector("#mensagem").textContent = valido ? "Reserva confirmada" : "Número inválido";\n});',[check('Três participantes custam 15 €.',"reserveCase('3',true,15)"),check('Aceita os limites 1 e 30.',"reserveCase('1',true,5) && reserveCase('30',true,150)"),check('Rejeita vazio, zero, mais de 30 e decimais.',"['','0','31','1.5'].every(n=>reserveCase(n,false,0))")],['Converte o valor com Number antes de o validar.','A condição é Number.isInteger(n) && n >= 1 && n <= 30.'],'<form novalidate><label>Participantes<input id="participantes" type="number" step="any" value="3"></label><button>Reservar</button><p id="mensagem"></p><p>Custo: <output id="custo"></output> €</p></form>');
add(4,'04 / A escola está de volta','html','Constrói uma página com header, main e footer. No main, cria .atividades em Grid com 2 colunas e pelo menos 2 cartões .cartao. Inclui um formulário com #participantes, um botão, #custo e #mensagem. Programa a reserva: 5 € por pessoa, inteiros de 1 a 30, com as mesmas mensagens do desafio anterior.','Este é o desafio de transferência. Junta estrutura, layout e comportamento. Podes usar <code>&lt;style&gt;</code> e <code>&lt;script&gt;</code> no editor.','<header><h1>Clube da Escola</h1></header>\n<main>\n  <!-- Grelha de atividades e formulário -->\n</main>\n<footer>Escola Digital</footer>\n<style>\n/* O teu CSS */\n</style>\n<script>\n// O teu JavaScript\n</script>','<header><h1>Clube da Escola</h1></header>\n<main>\n  <div class="atividades">\n    <article class="cartao">Robótica</article>\n    <article class="cartao">Ciência</article>\n  </div>\n  <form novalidate>\n    <label for="participantes">Participantes</label>\n    <input id="participantes" type="number" step="any" value="3">\n    <button>Reservar</button>\n    <p id="mensagem"></p>\n    <output id="custo"></output>\n  </form>\n</main>\n<footer>Escola Digital</footer>\n<style>\n.atividades { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }\n</style>\n<script>\ndocument.querySelector("form").addEventListener("submit", function (event) {\n  event.preventDefault();\n  const n = Number(document.querySelector("#participantes").value);\n  const valido = Number.isInteger(n) && n >= 1 && n <= 30;\n  document.querySelector("#custo").textContent = valido ? n * 5 : "";\n  document.querySelector("#mensagem").textContent = valido ? "Reserva confirmada" : "Número inválido";\n});\n</script>',[check('A página tem estrutura semântica e título.',"['header','main','footer'].every(s=>document.querySelector(s)) && !!document.querySelector('h1')?.textContent.trim()"),check('As atividades usam Grid com duas colunas e dois cartões.',"!!document.querySelector('.atividades') && getComputedStyle(document.querySelector('.atividades')).display==='grid' && getComputedStyle(document.querySelector('.atividades')).gridTemplateColumns.split(' ').length===2 && document.querySelectorAll('.atividades .cartao').length>=2"),check('O formulário confirma e calcula uma reserva.',"reserveCase('4',true,20) && reserveCase('30',true,150)"),check('O formulário rejeita quantidades inválidas.',"['','0','31','2.5'].every(n=>reserveCase(n,false,0))")],['Começa pela estrutura e pela grelha. Acrescenta depois o formulário.','Reutiliza a lógica do desafio anterior e testa cada parte.']);
